@logging
def retry(ExceptionToCheck, tries=3, delay=0):
    """Retry calling the decorated function using an exponential backoff.

    http://www.saltycrane.com/blog/2009/11/20/retrying-function-called-exception-backoff-python/
    """

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        attempt = 0
        while attempt < tries:
            try:
                return func(*args, **kwargs)
            except ExceptionToCheck as e:
                attempt += 1
                time.sleep(delay * (2 ** (attempt - 1)))
        return None
    return wrapper

