def gcd(a, b):
    # base case 
    if (a == 0): 
        return b 
    if (b == 0): 
        return a 

    # if both numbers are even 
    if (a % 2 == 0 and b % 2 == 0): 
        return 2 * gcd(a // 2, b // 2) 

    # if one number is even and other is odd 
    elif (a % 2 == 0): 
        return gcd(a // 2, b) 
    elif (b % 2 == 0): 
        return gcd(a, b // 2) 

    # if both numbers are odd 
    else: 
        return gcd((a - b) // 2, b) if (a > b) else gcd((b - a) // 2, a)

