def luhn_algorithm(number):
    # Reverse the number
    reversed_number = number[::-1]

    # Double every second digit
    for i in range(0, len(reversed_number)):
        if i % 2 == 1:
            doubled = int(reversed_number[i]) * 2
            if doubled > 9:
                doubled -= 9
            reversed_number = reversed_number[:i] + str(doubled) + reversed_number[i+1:]

    # Sum all the digits
    total = 0
    for digit in reversed_number:
        total += int(digit)

    # Check if the total is divisible by 10
    if total % 10 == 0:
        return True
    else:
        return False

