import functools

def logging(func):

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        print(f'Calling {func.__name__}')
        return func(*args, **kwargs)
    return wrapper

@logging
def retry_decorator(func):

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        attempts = 0
        while attempts < 3:
            try:
                return func(*args, **kwargs)
            except Exception as e:
                attempts += 1
        return None
    return wrapper

def gcd(a, b):
    # base case 
    if a == 0: 
        return b 
    if b == 0: 
        return a 

    # Euclidean algorithm 
    if a == b: 
        return a 
    if a > b: 
        return gcd(a-b, b) 
    return gcd(a, b-a) 

