import time

def rate_limiter(max_requests, interval):
    start_time = time.time()
    num_requests = 0

    def check_limit():
        nonlocal num_requests, start_time
        if time.time() - start_time >= interval:
            num_requests = 0
            start_time = time.time()

        if num_requests >= max_requests:
            return False
        else:
            num_requests += 1
            return True

    return check_limit

class Node:
