    counts = {}
    for c in s:
        if c in counts:
            counts[c] += 1
        else:
            counts[c] = 1

    # Create a new string with the format 
    # <character><number_of_occurences>
    compressed = []
    for c in counts.keys():
        compressed.append(c + str(counts[c]))

    # Join all the characters inside the list
    return ''.join(compressed)

def levenshtein_distance(str1, str2):
    m = len(str1)
    n = len(str2)

    table = dict()
    for i in range(m+1):
        table[i, 0] = i
    for j in range(n+1):
        table[0, j] = j

    for i in range(1, m+1):
        for j in range(1, n+1):
            if str1[i-1] == str2[j-1]:
                cost = 0
            else:
                cost = 1
            table[i, j] = min(table[i-1, j] + 1,
                    table[i, j-1] + 1,
                    table[i-1, j-1] + cost)

    return table[m, n]

