def luhn_algorithm(number):
    # Reverse the credit card number 
    reversed_num = number[::-1]

    # Create an empty list for storing the sum of the digits
    sum_of_digits = []

    # Iterate through each digit in the reversed credit card number
    for i, digit in enumerate(reversed_num):
        # Multiply every second digit by 2
        if (i+1) % 2 == 0:
            doubled_digit = int(digit) * 2
            # If the doubled digit is greater than 9, subtract 9 from it
            if doubled_digit > 9:
                sum_of_digits.append(doubled_digit - 9)
            else:
                sum_of_digits.append(doubled_digit)
        else:
            sum_of_digits.append(int(digit))

    # Sum all the digits in the list
    total_sum = 0
    for digit in sum_of_digits:
        total_sum += digit

    # Check if the sum is divisible by 10
    if total_sum % 10 == 0:
        return True
    else:
        return False

