    # Create an empty list to store prime numbers
    prime_numbers = []

    # Traverse through all numbers
    for i in range(2, num + 1):
        count = 0
        for j in range(2, i // 2 + 1):
            # If anything cleanly divides i, then don't consider it prime
            if (i % j == 0):
                count += 1
                break

        # If the number is prime then add it to the list of prime numbers
