import functools

def logging(func):

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        print(f'Calling {func.__name__}')
        return func(*args, **kwargs)
    return wrapper

@logging
def retry(func):

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        attempts = 0
        while True:
            try:
                return func(*args, **kwargs)
            except Exception as e:
                attempts += 1
                if attempts >= 3:
                    raise e
                else:
                    print('Retrying...')
    return wrapper

