def is_anagram(str1, str2):
    # Remove whitespace and covert strings to lowercase
    str1 = str1.replace(" ", "").lower()
    str2 = str2.replace(" ", "").lower()

    # If the lengths of the strings are not equal, they cannot be anagrams
    if len(str1) != len(str2):
        return False

    # Create dictionaries to store the frequency of each character in both strings
    char_freq_dict1 = {}
    char_freq_dict2 = {}

    # Fill the dictionaries with the frequencies
    for char in str1:
        if char in char_freq_dict1:
            char_freq_dict1[char] += 1
        else:
            char_freq_dict1[char] = 1

    for char in str2:
        if char in char_freq_dict2:
            char_freq_dict2[char] += 1
        else:
            char_freq_dict2[char] = 1

    # Compare the dictionaries
    return char_freq_dict1 == char_freq_dict2

