import random

def generate_markov_model(text, order=2):
    words = text.split()
    markov_model = {}

    for i in range(len(words)-order):
        key = tuple(words[i:i+order])
        value = words[i+order]

        if key in markov_model:
            markov_model[key].append(value)
        else:
            markov_model[key] = [value]

    return markov_model

def generate_text(markov_model, order=2):
    text = ""
    keys = list(markov_model.keys())
    random_start = random.choice(keys)

    for i in range(order):
        text += random_start[i] + " "

    while True:
        next_word = random.choice(markov_model[random_start])
        text += next_word + " "
        random_start = tuple(next_word[i] for i in range(order))

        if random_start not in markov_model:
            break

    return text

