        self.head = None

    def insert(self, data):
        node = Node(data)
        if self.head is None:
            self.head = node
        else:
            curr = self.head
            while curr.next != None:
                curr = curr.next
            curr.next = node

    def delete(self, data):
        if self.head == None:
            return 
        elif self.head.data == data:
            self.head = self.head.next
        else:
            curr = self.head
            while curr.next != None:
                if curr.next.data == data:
                    break
                curr = curr.next
            if curr.next == None:
                return 
            else:
                curr.next = curr.next.next

