def merge_sorted_lists(list1, list2):
    merged_list = []
    i = 0
    j = 0
    while i < len(list1) and j < len(list2):
        if list1[i] < list2[j]:
            merged_list.append(list1[i])
            i += 1
        else:
            merged_list.append(list2[j])
            j += 1

    # Lists might be of different lengths, so append the rest of the elements
    if i < len(list1):
        merged_list += list1[i:]
    elif j < len(list2):
        merged_list += list2[j:]

    return merged_list

