def flatten(lst):
    # empty list to add the flattened items
    flat_list = []

    # iterate through all items in lst
    for item in lst:
        # if item is a list, then recursively call the flatten function
        if type(item) is list:
            flat_list.extend(flatten(item))
        else:
            flat_list.append(item)
    # return the flattened list
    return flat_list

