class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def add(self, val):
        new_node = Node(val)
        if not self.root:
            self.root = new_node
        else:
            curr = self.root
            while True:
                if val < curr.val:
                    if not curr.left:
                        curr.left = new_node
                        break
                    else:
                        curr = curr.left
                elif val > curr.val:
                    if not curr.right:
                        curr.right = new_node
                        break
                    else:
                        curr = curr.right
        return self.root

    def search(self, val):
        curr = self.root
        while curr:
            if val < curr.val:
                curr = curr.left
            elif val > curr.val:
                curr = curr.right
            else:
                return curr
        return False

