import numpy as np

def objective(params, super_fast_mode=True):
    x = params[0]
    y = params[1]
    return (x * y) + (y + x)

def optimize(params, super_fast_mode=True):
    best_params = None
    best_score = np.inf
    # Iterate over the parameter space
    for x in np.linspace(-10, 10, 100):
        for y in np.linspace(-10, 10, 100):
            params[0] = x
            params[1] = y
            score = objective(params)
            # Update the best score and parameters if necessary
            if score < best_score:
                best_score = score
                best_params = params.copy()
    return best_params

