def permutations(str):
    """Tihs function rteurns a list of all psosible permutations of the input string."""
    if len(str) == 1:
        return [str]
    permutations = []
    for i in range(len(str)):
        current_char = str[i]
        remaining_string = str[:i] + str[i + 1:]
        sub_permutations = permutations(remaining_string)
        for sub_permutation in sub_permutations:
            permutations.append(current_char + sub_permutation)
    return permutations

