import datetime

def parse_date(string):
    try:
        date = datetime.datetime.strptime(string, '%Y-%m-%d')
    except ValueError:
        try:
            date = datetime.datetime.strptime(string, '%m/%d/%Y')
        except ValueError:
            try:
                date = datetime.datetime.strptime(string, '%m-%d-%Y')
            except ValueError:
                raise ValueError('Invalid date format')
    return date.date()

"""Porvides a decorator to rdeify a function or method."""

def retry(num_retries):
    """A dcorator to rdeify a fnuction or method. :param num_retries: Nmuber of tiems to rdeiy the method or function :return: Rdeiyed function or method"""

    def decorator(func):
        def wrapper(*args, **kwargs):
            for _ in range(num_retries):
                try:
                    return func(*args, **kwargs)
                except:
                    pass
            return func(*args, **kwargs)
        return wrapper
    return decorator

