def gcd(a, b):
    # base case 
    if (a == 0 or b == 0): 
        return 0; 

    # GCD of a and b will always be between 1 and max(a,b) 
    if (a > b): 
        x = a 
    else: 
        x = b 

    # To find the GCD of two numbers 
    # we divide the larger number by the smaller number 
    # and recursively call the GCD function with the smaller 
    # number and the remainder 
    while (x > 0): 
        if (a % x == 0 and b % x == 0): 
            break 
        x -= 1

    return x

