def is_balanced_parentheses(string):
    # Create an empty stack
    stack = []

    # Iterate through the characters in the string
    for char in string:
        if char == '(':
            # If the current character is an opening bracket, push it to the stack
            stack.append(char)
        elif char == ')':
            # If the current character is a closing bracket, pop one element from the stack
            # and check if the popped element is an opening bracket
            if len(stack) == 0 or stack.pop() != '(':
                return False

    # After iterating through all the characters, check if the stack is empty
    # If the stack is not empty, it means there are unmatched opening brackets
    if len(stack) != 0:
        return False

    # If the stack is empty, it means the parentheses are balanced
    return True

def merge_dicts(dict1, dict2):
    merged_dict = {}

    # Iterate through the first dictionary
    for key in dict1:
        if key in dict2:
            # If the key is present in both dictionaries, add the values
            merged_dict[key] = dict1[key] + dict2[key]
        else:
            # If the key is only present in the first dictionary, add it to the merged dictionary
            merged_dict[key] = dict1[key]

    # Iterate through the second dictionary
    for key in dict2:
        if key in dict1:
            # If the key is present in both dictionaries, add the values
            merged_dict[key] = dict1[key] + dict2[key]
        else:
            # If the key is only present in the second dictionary, add it to the merged dictionary
            merged_dict[key] = dict2[key]

    return merged_dict

