import random

# Build the Markov Chain
def build_chain(text):
  chain = {}
  for i in range(len(text)-2):
    key = (text[i], text[i+1])
    value = text[i+2]
    if key in chain:
      chain[key].append(value)
    else:
      chain[key] = [value]
  return chain

# Generate text
def generate_text(chain, length):
  text = []
  # Start with a random two-word phrase
  keys = list(chain.keys())
  random_key = keys[random.randint(0, len(keys)-1)]
  text.extend(random_key)

  # Generate the rest of the text
  while len(text) < length:
    try:
      value_list = chain[tuple(text[-2:])]
      word = value_list[random.randint(0, len(value_list)-1)]
      text.append(word)
    except KeyError:
      break

  return ' '.join(text)

