import time

def rate_limiter(max_requests, interval):
    # comment: Initialize the request counter
    requests = {}

    def limiter(func):
        def wrapper(*args, **kwargs):
            # comment: Get the timestamp
            timestamp = time.time()

            # comment: Count the number of requests in the given interval
            count = 0
            for k, v in requests.items():
                if v > timestamp - interval:
                    count += 1

            # comment: Reset the counter if the interval has passed
            if count >= max_requests:
                if args[0] in requests:
                    del requests[args[0]]

            # comment: Update the request counter
            requests[args[0]] = timestamp
            return func(*args, **kwargs)
        return wrapper
    return limiter

class Node:
