def find_longest_ride(arr_z):
    max_duration_z = 0
    for i_z in range(len(arr_z)):
        for j_z in range(i_z + 1, len(arr_z)):
            duration_z = arr_z[j_z] - arr_z[i_z]
            if duration_z > max_duration_z:
                max_duration_z = duration_z
    return max_duration_z
