def compress_string(s): 
    # Count occurences of each character 
    dict = {} 
    for c in s: 
        if c in dict: 
            dict[c] += 1
        else: 
            dict[c] = 1

    # Create a new string with the format 
    # <character><number_of_occurences>
    compressed = [] 
    for c in dict.keys(): 
        compressed.append(c + str(dict[c])) 

    # Join all the characters inside the list 
    return ''.join(compressed)

def levenshteinDistance(str1, str2):
    m = len(str1)
    n = len(str2)

    dp = [[0 for x in range(n + 1)] for x in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):

            if i == 0:
                dp[i][j] = j
            elif j == 0:
                dp[i][j] = i
            elif str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i][j - 1],        # Insert
                                   dp[i - 1][j],        # Remove
                                   dp[i - 1][j - 1])    # Replace

    return dp[m][n]

