class Stack: 
    def __init__(self): 
        self.queue1 = [] 
        self.queue2 = []

    def push(self,data):
        self.queue1.append(data)


    def pop(self):
        if len(self.queue1) == 0:
            return None
        while(len(self.queue1) > 1):
            temp = self.queue1.pop(0)
            self.queue2.append(temp)

        elem = self.queue1.pop(0)
        self.queue1, self.queue2 = self.queue2, self.queue1
        return elem

