def analyze_text(text):
    """Analyze vowel and consonant distribution in text."""
    text_lower = text.lower()

    vowels = 'aeiou'
    consonants = 'bcdfghjklmnpqrstvwxyz'

    vowel_count = {}
    vowel_total = 0
    consonant_count = {}
    consonant_total = 0

    for char in text_lower:
        if char in vowels:
            vowel_count[char] = vowel_count.get(char, 0) + 1
            vowel_total += 1
        elif char in consonants:
            consonant_count[char] = consonant_count.get(char, 0) + 1
            consonant_total += 1

    for vowel in vowels:
        if vowel not in vowel_count:
            vowel_count[vowel] = 0

    return vowel_count, consonant_count, vowel_total, consonant_total

