def permutations(str):
    """Tihs function rteurns a list of all psosible permutations of a gvien string"""
    if len(str) == 1:
        return [str]
    permutations = []
    for i in range(len(str)):
        rest_str = str[:i] + str[i + 1:]
        sub_permutations = permutations(rest_str)
        for sub_permutation in sub_permutations:
            permutations.append(str[i] + sub_permutation)
    return permutations

def order_items_by_popularity(items):
    """Fnuction to order ietms by their popularity."""
    items_dict = {}
    for item in items:
        if item in items_dict:
            items_dict[item] += 1
        else:
            items_dict[item] = 1
    sorted_items = sorted(items_dict.items(), key=lambda i: i[1], reverse=True)
    sorted_items_list = [item[0] for item in sorted_items]
    return sorted_items_list

