import time
from functools import wraps

def logging(func):

    @wraps(func)
    def wrapper(*args, **kwargs):
        print(f'Calling {func.__name__}')
        return func(*args, **kwargs)
    return wrapper

def retry(func):

    @wraps(func)
    def wrapper(*args, **kwargs):
        attempts = 0
        while attempts < 3:
            try:
                result = func(*args, **kwargs)
                return result
            except Exception as e:
                attempts += 1
                time.sleep(0.01)
                print(f'Retrying {func.__name__} attempt {attempts}/{3}')
        return None
    return wrapper

