def merge_dicts(dict1, dict2):
    """
    Merge two dictionaries, summing values for duplicate keys.
    Args:
        dict1 (dict): Dictionary 1
        dict2 (dict): Dictionary 2
    Returns:
        dict: Merged dictionary
    """
    merged_dict = {}

    # Iterate through the first dictionary
    for key, value in dict1.items():
        # If the key is present in both dictionaries
        if key in dict2:
            # Add the values together
            merged_dict[key] = dict2[key] + value
        else:
            # Otherwise, set the value to the value from the first dictionary
            merged_dict[key] = value

    # Repeat for the second dictionary
    for key, value in dict2.items():
        if key in dict1:
            merged_dict[key] = dict1[key] + value
        else:
            merged_dict[key] = value

    return merged_dict

