        return func(*args, **kwargs)
    return wrapper
import math

@logging
def calculate_rocket_trajectory(initial_velocity, angle, wind_velocity):
    g = 9.8
    (vx0, vy0) = (initial_velocity * math.cos(angle), initial_velocity * math.sin(angle))
    (wx, wy) = wind_velocity
    t_max = 2 * vy0 / g
    x_max = vx0 * t_max + wx * t_max
    y_max = vy0 * t_max - 0.5 * g * t_max ** 2 + wy * t_max
    return (x_max, y_max)

