import random

def generate_markov_model(text, order=2):
    # Split the text into words
    words = text.split()
    # Create a dictionary to store the Markov model
    model = {}
    # Iterate over the words and create the model
    for i in range(len(words)-order):
        key = tuple(words[i:i+order])
        value = words[i+order]
        if key in model:
            model[key].append(value)
        else:
            model[key] = [value]
    return model

def generate_text(model, order=2, seed=None):
    # If seed is not provided, pick a random seed
    if seed is None:
        seed = random.randint(0, len(words)-order)
    # Initialize the output
    output = []
    # Add the seed to the output
    output.extend(words[seed:seed+order])
    # Generate the rest of the output
    while True:
        key = tuple(words[seed:seed+order])
        if key not in model:
            break
        value = random.choice(model[key])
        output.append(value)
        seed += 1
    return ' '.join(output)

def determine_grade(marks):
    # Determine the average mark
    avg = (marks['math'] + marks['history'] + marks['english'])/3

    # If the average mark is greater than or equal to 90, the student's grade is A 
    if avg >= 90:
        return 'A'
    # If the average mark is greater than or equal to 80, the student's grade is B 
    elif avg >= 80:
        return 'B'
    # If the average mark is greater than or equal to 70, the student's grade is C 
    elif avg >= 70:
        return 'C'
    # If the average mark is greater than or equal to 60, the student's grade is D 
    elif avg >= 60:
        return 'D'
    # Anything less than 60 is an F 
    else:
        return 'F'

